import random

def random_cubic_graph(n):
    """Generate a random 3-regular graph on n vertices (n must be even)"""
    if n % 2 != 0:
        return None
    # Create a list of stubs
    stubs = []
    for i in range(n):
        stubs.extend([i] * 3)
    # Randomly pair stubs
    while True:
        random.shuffle(stubs)
        edges = set()
        ok = True
        for i in range(0, len(stubs), 2):
            u, v = stubs[i], stubs[i+1]
            if u == v:
                ok = False
                break
            if u > v:
                u, v = v, u
            if (u, v) in edges:
                ok = False
                break
            edges.add((u, v))
        if ok and len(edges) == n * 3 // 2:
            return list(edges)
        # Try again

def build_adjacency(edges, n):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    return adj

def shortest_cycle(adj):
    """Find the length of the shortest cycle"""
    n = len(adj)
    min_cycle = n + 1
    for start in range(n):
        dist = {start: 0}
        parent = {start: -1}
        queue = [start]
        while queue:
            v = queue.pop(0)
            for w in adj[v]:
                if w not in dist:
                    dist[w] = dist[v] + 1
                    parent[w] = v
                    queue.append(w)
                elif w != parent[v]:
                    # Found a cycle
                    cycle_len = dist[v] + dist[w] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
        if min_cycle <= 6:
            return min_cycle
    return min_cycle

def is_3_colorable_adj(adj):
    n = len(adj)
    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        used = set()
        for w in adj[v]:
            if colors[w] != -1:
                used.add(colors[w])
        for c in range(3):
            if c not in used:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

# Try random search for a cubic graph with girth >= 7
print("Searching for a cubic graph with girth >= 7...")
best_girth = 0
for attempt in range(10000):
    edges = random_cubic_graph(24)
    if edges is None:
        continue
    adj = build_adjacency(edges, 24)
    g = shortest_cycle(adj)
    if g > best_girth:
        best_girth = g
        if g >= 7:
            print(f"Found! Girth = {g}")
            print(f"Edges: {edges}")
            print(f"3-colorable: {is_3_colorable_adj(adj)}")
            break
    if attempt % 1000 == 0:
        print(f"Attempt {attempt}, best girth so far: {best_girth}")
